const arr=v=>Array.isArray(v)?v:(typeof v==='string'?JSON.parse(v||'[]'):(v||[]));
return [{ json:{ period:meta.period, device_id:meta.device_id, region:meta.region, byPeriod:arr(r.byperiod), byRegion:arr(r.byregion), byDevice:arr(r.bydevice) } }];
